-- db/migrations/0001_baseline.sql
--
-- Full ISMS Portal schema as of 2026-10-01, written so it is SAFE TO RUN ON
-- ANY DATABASE — empty, or an older one set up by hand from the legacy SQL
-- files (db/legacy/) or a backup: missing tables and columns are created,
-- constraints/indexes are only added when nothing equivalent exists, and
-- nothing is ever dropped. A constraint that old data violates is skipped
-- with a WARNING instead of failing the whole migration.
--
-- Generated from the live schema (pg_catalog); edit by adding a NEW
-- migration file, never by changing this one after it has been applied.

-- ─── sequences (serial columns) ───
CREATE SEQUENCE IF NOT EXISTS education_documents_id_seq;
CREATE SEQUENCE IF NOT EXISTS activity_log_id_seq;
CREATE SEQUENCE IF NOT EXISTS schedule_documents_id_seq;
CREATE SEQUENCE IF NOT EXISTS standard_isms_p14_documents_id_seq;
