-- ─── tables ───
CREATE TABLE IF NOT EXISTS activity_log (
  id integer DEFAULT nextval('activity_log_id_seq'::regclass) NOT NULL,
  actor_username character varying(100) NOT NULL,
  actor_role character varying(20) NOT NULL,
  action character varying(30) NOT NULL,
  entity_type character varying(60) NOT NULL,
  entity_id character varying(60),
  description text NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE IF NOT EXISTS admins (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  username character varying(50) NOT NULL,
  email character varying(100),
  password_hash text NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  role character varying(20) DEFAULT 'ism_admin'::character varying NOT NULL
);
CREATE TABLE IF NOT EXISTS app_settings (
  key character varying(60) NOT NULL,
  value jsonb NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_by character varying(100)
);
CREATE TABLE IF NOT EXISTS audit_schedule (
  id integer GENERATED ALWAYS AS IDENTITY NOT NULL,
